scenarios.prompt:
Launching a Black Friday promo tomorrow. Our Express service wraps this module in POST /coupons/apply. This is all the code and all the tests we have. What's missing, and what's not worth keeping? Tell me what to write.

```js
// coupon.js
const COUPONS = new Map();
function create(code, pct, maxUses, expiresAt) {
  if (pct <= 0 || pct > 100) throw new Error('bad pct');
  COUPONS.set(code, { code, pct, maxUses, used: 0, expiresAt });
}
function apply(code, cartTotal, now = Date.now()) {
  const c = COUPONS.get(code);
  if (!c) throw new Error('unknown');
  if (now > c.expiresAt) throw new Error('expired');
  if (c.used >= c.maxUses) throw new Error('exhausted');
  c.used++;
  return Math.round(cartTotal * (1 - c.pct / 100) * 100) / 100;
}
function getCode(c) { return c.code; }
```

```js
// coupon.test.js
test('creates coupon', () => { create('A', 10, 5, 9e12); });
test('applies 10 percent', () => { expect(apply('A', 100)).toEqual(90); });
test('getCode returns code', () => { expect(getCode({code:'x'})).toEqual('x'); });
test('apply works twice', () => { apply('A', 50); apply('A', 50); });
```
